def two_phase_commit(txn, participants):
    # phase 1: prepare，参与者写 prepare log 并锁住相关行
    votes = [p.prepare(txn) for p in participants]

    # phase 2: all-or-nothing decision
    if all(v == 'READY' for v in votes):
        for p in participants:
            p.commit(txn)
    else:
        for p in participants:
            p.rollback(txn)

